import { useState } from "react";
import { login, register, getMe, verifyOTP, resendOTP } from "../services/api";
import { G } from "../App";

// mode: "login" | "register" | "verify-otp"
export default function Login({ onLogin }) {
  const [mode, setMode]       = useState("login");
  const [form, setForm]       = useState({ name: "", email: "", password: "" });
  const [otp, setOtp]         = useState("");
  const [msg, setMsg]         = useState("");
  const [loading, setLoading] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);

  const isSuccess = (m) => typeof m === "string" && m.startsWith("✅");
  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  // ── Register ─────────────────────────────────────────────────────────
  const handleRegister = async () => {
    if (!form.name || !form.email || !form.password) { setMsg("Please fill all fields."); return; }
    setMsg(""); setLoading(true);
    try {
      await register({ name: form.name, email: form.email, password: form.password });
      setMsg("✅ OTP sent to your email! Check your inbox.");
      setMode("verify-otp");
    } catch (e) {
      setMsg(e.response?.data?.detail || "Registration failed.");
    }
    setLoading(false);
  };

  // ── Verify OTP ────────────────────────────────────────────────────────
  const handleVerifyOTP = async () => {
    if (otp.length !== 6) { setMsg("Please enter the 6-digit OTP."); return; }
    setMsg(""); setLoading(true);
    try {
      await verifyOTP({ email: form.email, otp });
      setMsg("✅ Email verified! You can now log in.");
      setMode("login");
      setOtp("");
    } catch (e) {
      setMsg(e.response?.data?.detail || "Invalid OTP.");
    }
    setLoading(false);
  };

  // ── Resend OTP ────────────────────────────────────────────────────────
  const handleResend = async () => {
    if (resendCooldown > 0) return;
    setMsg(""); setLoading(true);
    try {
      await resendOTP({ email: form.email });
      setMsg("✅ New OTP sent to your email!");
      setResendCooldown(30);
      const timer = setInterval(() => {
        setResendCooldown(c => { if (c <= 1) { clearInterval(timer); return 0; } return c - 1; });
      }, 1000);
    } catch (e) {
      setMsg(e.response?.data?.detail || "Failed to resend OTP.");
    }
    setLoading(false);
  };

  // ── Login ─────────────────────────────────────────────────────────────
  const handleLogin = async () => {
    if (!form.email || !form.password) { setMsg("Please fill all fields."); return; }
    setMsg(""); setLoading(true);
    try {
      const res   = await login({ email: form.email, password: form.password });
      const token = res.data.access_token;
      localStorage.setItem("token", token);
      const me    = await getMe();
      onLogin(me.data, token);
    } catch (e) {
      setMsg(e.response?.data?.detail || "Login failed.");
    }
    setLoading(false);
  };

  const submit = mode === "login" ? handleLogin : mode === "register" ? handleRegister : handleVerifyOTP;

  const s = {
    page: { minHeight: "100vh", background: G.bg, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: G.font, position: "relative", overflow: "hidden" },
    glow: { position: "absolute", width: 400, height: 400, borderRadius: "50%", background: `radial-gradient(circle, ${G.accent}15 0%, transparent 70%)`, top: "10%", left: "50%", transform: "translateX(-50%)", pointerEvents: "none" },
    card: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 20, padding: "40px 44px", width: 420, position: "relative", zIndex: 1 },
    topBar: { height: 3, background: `linear-gradient(90deg, ${G.accent}, ${G.accent2})`, borderRadius: "20px 20px 0 0", margin: "-40px -44px 32px" },
    title: { fontWeight: 900, fontSize: 26, letterSpacing: "-0.5px", marginBottom: 4 },
    sub: { color: G.muted, fontSize: 13, marginBottom: 28 },
    label: { fontSize: 11, color: G.muted, letterSpacing: 1.5, textTransform: "uppercase", fontWeight: 600, marginBottom: 6, display: "block" },
    input: { width: "100%", background: `${G.border}60`, border: `1px solid ${G.border}`, borderRadius: 10, padding: "12px 14px", color: G.text, fontSize: 14, fontFamily: G.font, marginBottom: 16 },
    otpInput: { width: "100%", background: `${G.border}60`, border: `2px solid ${G.accent}50`, borderRadius: 10, padding: "16px 14px", color: G.text, fontSize: 28, fontFamily: "'JetBrains Mono', monospace", marginBottom: 16, textAlign: "center", letterSpacing: 12 },
    btn: { width: "100%", padding: "13px", background: `linear-gradient(135deg, ${G.accent}cc, ${G.accent2})`, border: "none", borderRadius: 10, color: "#fff", fontWeight: 700, fontSize: 14, cursor: loading ? "wait" : "pointer", fontFamily: G.font, marginTop: 4, letterSpacing: 0.5 },
    toggle: { textAlign: "center", marginTop: 20, fontSize: 13, color: G.muted },
    toggleLink: { color: G.accent, cursor: "pointer", fontWeight: 600, marginLeft: 4 },
    msgBox: { background: isSuccess(msg) ? `${G.green}15` : `${G.red}15`, border: `1px solid ${isSuccess(msg) ? G.green : G.red}40`, borderRadius: 8, padding: "10px 14px", fontSize: 13, color: isSuccess(msg) ? G.green : G.red, marginBottom: 16 },
    resendBtn: { background: "none", border: "none", color: resendCooldown > 0 ? G.muted : G.accent, cursor: resendCooldown > 0 ? "default" : "pointer", fontSize: 13, fontFamily: G.font, fontWeight: 600, padding: 0 },
    emailBadge: { background: `${G.accent}15`, border: `1px solid ${G.accent}30`, borderRadius: 8, padding: "8px 14px", fontSize: 13, color: G.accent, marginBottom: 16, textAlign: "center" },
  };

  return (
    <div style={s.page}>
      <div style={s.glow} />
      <div style={s.card} className="fade-in">
        <div style={s.topBar} />

        <div style={{ textAlign: "center", marginBottom: 28 }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>💸</div>
          <div style={s.title}>ExpenseIQ</div>
          <div style={s.sub}>
            {mode === "login" ? "Sign in to your account" : mode === "register" ? "Create your account" : "Verify your email"}
          </div>
        </div>

        {msg && <div style={s.msgBox}>{msg}</div>}

        {/* ── OTP Verification Screen ── */}
        {mode === "verify-otp" && (
          <>
            <div style={s.emailBadge}>📧 OTP sent to {form.email}</div>
            <label style={s.label}>Enter 6-Digit OTP</label>
            <input
              style={s.otpInput}
              type="text"
              maxLength={6}
              placeholder="000000"
              value={otp}
              onChange={e => setOtp(e.target.value.replace(/\D/g, ""))}
              onKeyDown={e => e.key === "Enter" && handleVerifyOTP()}
            />
            <button style={s.btn} onClick={handleVerifyOTP} disabled={loading}>
              {loading ? "Verifying..." : "Verify OTP"}
            </button>
            <div style={{ textAlign: "center", marginTop: 16, fontSize: 13, color: G.muted }}>
              Didn't receive it?{" "}
              <button style={s.resendBtn} onClick={handleResend} disabled={loading || resendCooldown > 0}>
                {resendCooldown > 0 ? `Resend in ${resendCooldown}s` : "Resend OTP"}
              </button>
            </div>
            <div style={{ textAlign: "center", marginTop: 10 }}>
              <span style={s.toggleLink} onClick={() => { setMode("register"); setMsg(""); setOtp(""); }}>
                ← Back to Register
              </span>
            </div>
          </>
        )}

        {/* ── Register Screen ── */}
        {mode === "register" && (
          <>
            <label style={s.label}>Full Name</label>
            <input style={s.input} placeholder="Vighnesh Nadar" value={form.name} onChange={set("name")} onKeyDown={e => e.key === "Enter" && submit()} />
            <label style={s.label}>Email</label>
            <input style={s.input} type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} onKeyDown={e => e.key === "Enter" && submit()} />
            <label style={s.label}>Password</label>
            <input style={s.input} type="password" placeholder="Min 8 characters" value={form.password} onChange={set("password")} onKeyDown={e => e.key === "Enter" && submit()} />
            <button style={s.btn} onClick={handleRegister} disabled={loading}>
              {loading ? "Sending OTP..." : "Create Account"}
            </button>
            <div style={s.toggle}>
              Already have an account?
              <span style={s.toggleLink} onClick={() => { setMode("login"); setMsg(""); }}>Sign In</span>
            </div>
          </>
        )}

        {/* ── Login Screen ── */}
        {mode === "login" && (
          <>
            <label style={s.label}>Email</label>
            <input style={s.input} type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} onKeyDown={e => e.key === "Enter" && submit()} />
            <label style={s.label}>Password</label>
            <input style={s.input} type="password" placeholder="••••••••" value={form.password} onChange={set("password")} onKeyDown={e => e.key === "Enter" && submit()} />
            <button style={s.btn} onClick={handleLogin} disabled={loading}>
              {loading ? "Signing in..." : "Sign In"}
            </button>
            <div style={s.toggle}>
              Don't have an account?
              <span style={s.toggleLink} onClick={() => { setMode("register"); setMsg(""); }}>Register</span>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
